-- DRAFTS: a rehearsal file (every draft fact and row). Never apply it to production.
-- L02-K2-team-accounts.rollback.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   undoes L02. Refused while a Team account has a quiz (deleting the profile would delete its quizzes).
-- Note:   the auth users stay. To remove them too (owner, SQL editor): delete from auth.users where email like '%@team.otakuquiz.org';
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if exists (select 1 from public.quizzes q join public.profiles p on p.id = q.creator_id where p.username in ('oq_creator_01', 'oq_creator_02', 'oq_creator_03', 'oq_creator_04', 'oq_creator_05', 'oq_creator_06', 'oq_creator_07', 'oq_creator_08', 'oq_creator_09', 'oq_creator_10', 'oq_creator_11', 'oq_creator_12', 'oq_creator_13', 'oq_creator_14', 'oq_creator_15', 'oq_creator_16', 'oq_creator_17', 'oq_creator_18', 'oq_creator_19', 'oq_creator_20', 'oq_creator_21', 'oq_creator_22', 'oq_creator_23', 'oq_creator_24', 'oq_creator_25', 'oq_creator_26', 'oq_creator_27', 'oq_creator_28', 'oq_creator_29', 'oq_creator_30', 'otakuquiz_team')) then
    raise exception 'L02 rollback refused: a Team account still has quizzes; roll back L07 first';
  end if;
end $o1l$;

update public.sites set system_user_id = null, fallback_group_slug = null where id = 'anime';

delete from public.editorial_accounts where site_id = 'anime' and user_id in (select id from public.profiles where username in ('oq_creator_01', 'oq_creator_02', 'oq_creator_03', 'oq_creator_04', 'oq_creator_05', 'oq_creator_06', 'oq_creator_07', 'oq_creator_08', 'oq_creator_09', 'oq_creator_10', 'oq_creator_11', 'oq_creator_12', 'oq_creator_13', 'oq_creator_14', 'oq_creator_15', 'oq_creator_16', 'oq_creator_17', 'oq_creator_18', 'oq_creator_19', 'oq_creator_20', 'oq_creator_21', 'oq_creator_22', 'oq_creator_23', 'oq_creator_24', 'oq_creator_25', 'oq_creator_26', 'oq_creator_27', 'oq_creator_28', 'oq_creator_29', 'oq_creator_30', 'otakuquiz_team'));

